type Row = Record<string, unknown>;
type ViewerRole = "admin" | "professional" | "participant" | "reviewer";
type Viewer = { id: string; role: ViewerRole; name: string; email: string; status: string };
type Credentials = { email: string; password: string; emailed: boolean } | null;
type AppData = { viewer: Viewer; professionalSpecialty?:string; preview?:{role:string;label:string;targetId?:string}; participants?: Row[]; professionals?:Row[]; administrators?:Row[]; habitDaily?:Row[]; nutritionDaily?:Row[]; adherenceOutreach?:Row[]; programs?: Row[]; programGuides?:Row[]; exercises?: Row[]; workouts?: Row[]; workoutExercises?: Row[]; content?: Row[]; sessions?: Row[]; meetingRequests?:Row[]; profile?: Row; nutrition?: Row | null; nutritionGuidePdf?: string | null; macrosVisible?:boolean; checkpoints?: Row[]; metrics?: Row[]; adherence?:Row|null; intakeQuestions?:Row[]; intakeResponses?:Row[]; notes?:Row[]; notices?:Row[] };
type Modal = null | "participant" | "professional" | "professional-edit" | "admin" | "admin-edit" | "program" | "workout" | "workout-edit" | "exercise" | "exercise-edit" | "attach" | "attach-edit" | "nutrition" | "content" | "session" | "meeting-review" | "participant-edit" | "participant-body" | "intake-view" | "professional-student";

const TOOLS="Contenido/Herramientas";
const adminNavLegacy = ["Resumen", "Participantes", "Adherencia", "Seguimiento", "Profesionales", "Programas", "Nutrición", TOOLS, "Sesiones", "Primer ingreso"];
const adminNavPanel = ["Resumen", "Participantes", PANEL_SCREEN, "Profesionales", "Programas", "Nutrición", TOOLS, "Sesiones", "Primer ingreso"];
const participantNav = ["Inicio", "Mi Semana", "Entrenamiento", "Alimentación", "Progreso", TOOLS, "Comentarios"];
const iconMap: Record<string,string> = { Resumen:"⌂",Participantes:"◎",Adherencia:"▦",Seguimiento:"◉",[PANEL_SCREEN]:"▦",Profesionales:"♙",Programas:"↗",Nutrición:"◒",[TOOLS]:"◇",Sesiones:"▣","Primer ingreso":"?",Inicio:"⌂","Mi Semana":"☷",Entrenamiento:"↗",Alimentación:"◒",Progreso:"◎",Comentarios:"✉" };
function staffNav(role:string, specialty:string|undefined, panelEnabled:boolean){
  if(role==="admin"||role==="reviewer") return panelEnabled?adminNavPanel:adminNavLegacy;
  if(specialty==="nutrition") return panelEnabled?["Resumen","Participantes","Nutrición",PANEL_SCREEN,TOOLS]:["Resumen","Participantes","Nutrición","Seguimiento",TOOLS];
  return panelEnabled?["Resumen","Participantes",PANEL_SCREEN,"Programas","Sesiones",TOOLS]:["Resumen","Participantes","Seguimiento","Programas","Sesiones",TOOLS];
}
const appNow=Date.now();
const appToday=new Date(appNow);

const authHeaders = () => ({
  "Authorization": `Token ${localStorage.getItem("p90_token") || ""}`,
  "X-Branch-ID": localStorage.getItem("p90_branch") || "",
});
const API_BASE=(import.meta.env.VITE_API_BASE as string||"");
const apiUrl=(p:string)=>API_BASE+p;
function toLocalInput(value:unknown){const raw=String(value||"");if(!raw)return "";const date=new Date(raw);if(Number.isNaN(date.getTime()))return raw.slice(0,16);const pad=(n:number)=>String(n).padStart(2,"0");return `${date.getFullYear()}-${pad(date.getMonth()+1)}-${pad(date.getDate())}T${pad(date.getHours())}:${pad(date.getMinutes())}`}
async function openPdf(key:string){const res=await fetch(apiUrl(`/api/files?key=${encodeURIComponent(key)}`),{headers:authHeaders()});if(!res.ok){alert("No fue posible abrir el PDF");return}const url=URL.createObjectURL(await res.blob());window.open(url,"_blank")}

export function FunctionalApp({ initialViewer,initialData,onLogout }: { initialViewer: Viewer;initialData?:AppData;onLogout?:()=>void }) {
  const [data,setData]=useState<AppData|null>(initialData||null); const [screen,setScreen]=useState(initialViewer.role==="participant"?"Inicio":"Resumen");
  const [loading,setLoading]=useState(!initialData); const [modal,setModal]=useState<Modal>(null); const [context,setContext]=useState<Row>({});
  const [toast,setToast]=useState(""); const [error,setError]=useState(""); const [selected,setSelected]=useState<string[]>([]);
  const [credentials,setCredentials]=useState<Credentials>(null);
  const [previewTarget,setPreviewTarget]=useState("admin");
  const [panelConfig,setPanelConfig]=useState<PanelConfig|null>(null);
  const firstLoad=useRef(true);
  const activeRole=data?.viewer.role||initialViewer.role;
  const panelEnabled=staffPanelActive(panelConfig);
  const nav=activeRole==="participant"?participantNav:staffNav(activeRole,data?.professionalSpecialty,panelEnabled);
  function goScreen(name:string){setScreen(panelEnabled?normalizeScreen(name):name)}
  async function load(){setLoading(true);const params=new URLSearchParams();if(previewTarget==="coach"||previewTarget==="nutrition")params.set("viewAs",previewTarget);else if(previewTarget.startsWith("participant:")){params.set("viewAs","participant");params.set("participantId",previewTarget.slice(12))}const res=await fetch(apiUrl(`/api/app${params.size?`?${params}`:""}`),{headers:authHeaders(),cache:"no-store"});const json=await res.json();if(!res.ok)setError(json.error||"No fue posible cargar");else setData(json);setLoading(false)}
  // Initial synchronization with the durable Sites database.
  useEffect(()=>{if(firstLoad.current){firstLoad.current=false;if(initialData)return}load()},[previewTarget]);
  useEffect(()=>{
    const ac=new AbortController();
    fetchPanelConfig(ac.signal).then(setPanelConfig).catch((err:unknown)=>{
      if((err as Error).name==="AbortError") return;
      // Alumno suele recibir 403 en /panel/config: usamos defaults del PR #80.
      if(activeRole==="participant") setPanelConfig(normalizePanelConfig(null));
      else setPanelConfig(null);
    });
    return ()=>ac.abort();
  },[activeRole,previewTarget]);
  useEffect(()=>{
    setScreen(s=>{
      if(panelEnabled) return normalizeScreen(s);
      if(s===PANEL_SCREEN) return activeRole==="professional"?"Seguimiento":"Adherencia";
      return s;
    });
  },[panelEnabled,activeRole]);
  async function act(payload:Row){if(previewTarget.startsWith("participant:")){setError("La vista de alumno es de solo lectura.");throw new Error("solo lectura")}setError("");const res=await fetch(apiUrl("/api/app"),{method:"POST",headers:{"content-type":"application/json",...authHeaders()},body:JSON.stringify(payload)});const json=await res.json();if(!res.ok){setError(json.error||"No fue posible guardar");throw new Error(json.error)}const tempPassword=String(json.tempPassword||"");if(tempPassword)setCredentials({email:payload.email?String(payload.email):"",password:tempPassword,emailed:json.credentialsEmailed!==false});setToast(json.message||"Guardado");setTimeout(()=>setToast(""),2600);await load();return json}
  function changePreview(value:string){setModal(null);setSelected([]);setError("");setScreen(value.startsWith("participant:")?"Inicio":"Resumen");setPreviewTarget(value)}
  function open(next:Modal,row:Row={}){setContext(row);setError("");setModal(next)}
  function nextNutrition(currentId:string){const next=(data?.participants||[]).find(x=>!x.nutrition_id&&String(x.id)!==currentId);if(next)setContext(next);else setModal(null)}
  // Fichas abiertas se refrescan con los datos recargados (p. ej. tras corregir peso/estatura).
  const liveContext=(modal==="intake-view"||modal==="participant-body")&&context.id?{...context,...((data?.participants||[]).find(x=>String(x.id)===String(context.id))||{})}:context;
  if(loading&&!data)return <div className="app-loading"><img className="brand-wordmark loading-logo" src="/proyecto90-logo.jpg" alt="Proyecto 90" width="384" height="384"/><p>Preparando tu Proyecto 90…</p></div>;
  if(!data)return <div className="app-loading"><p>{error||"No fue posible cargar la plataforma."}</p><button className="primary" onClick={load}>Reintentar</button></div>;
  return <div className={`app-shell ${data.viewer.role==="participant"?"participant-shell":"admin-shell"} role-${data.professionalSpecialty||data.viewer.role} ${data.viewer.role==="reviewer"?"reviewer-shell":""} ${data.preview?"admin-preview-shell":""} ${data.preview?.role==="participant"?"admin-preview-participant":""}`}>
    <aside className="sidebar"><button className="brand" onClick={()=>goScreen(nav[0])}><img className="brand-wordmark" src="/proyecto90-logo.jpg" alt="Proyecto 90" width="384" height="384"/><small>90 DÍAS · GENERACIÓN 01</small></button><nav>{nav.map(x=><button key={x} className={screen===x?"active":""} onClick={()=>goScreen(x)}><span className="nav-icon">{iconMap[x]}</span>{x}</button>)}</nav><div className="sidebar-spacer"/><div className="side-quote"><span>“</span><p>No buscamos hacerlo perfecto.<br/>Buscamos hacerlo parte de tu vida.</p></div><div className="profile-mini"><span className="avatar">{initials(data.viewer.name)}</span><span><strong>{data.viewer.name}</strong><small>{roleLabel(data.viewer.role)}</small></span></div></aside>
    <main><header className="topbar"><div className="mobile-brand"><img className="brand-wordmark" src="/proyecto90-logo.jpg" alt="Proyecto 90" width="384" height="384"/></div><div className="top-actions">{initialViewer.role==="admin"&&<label className="view-as-control"><span>Ver como</span><select value={previewTarget} onChange={e=>changePreview(e.target.value)}><option value="admin">Administrador</option><option value="coach">Coach</option><option value="nutrition">Nutricionista</option>{(previewTarget==="admin"?data.participants||[]:[]).length>0&&<optgroup label="Alumnos">{(data.participants||[]).map(p=><option key={String(p.id)} value={`participant:${String(p.id)}`}>{`${p.first_name||""} ${p.last_name||""}`.trim()||String(p.email)}</option>)}</optgroup>}{previewTarget.startsWith("participant:")&&<option value={previewTarget}>{data.preview?.label||"Alumno"}</option>}</select></label>}<span className="secure-pill">● Datos guardados</span><span className="user-email">{initialViewer.email}</span><button type="button" className="logout" onClick={()=>onLogout?onLogout():window.location.reload()}>Salir</button></div></header>{data.viewer.role==="reviewer"&&<div className="reviewer-banner">Modo Revisor · Navegación de solo lectura. No puedes guardar, aprobar ni eliminar información.</div>}{data.preview&&<div className="preview-banner"><div><b>Vista de prueba: {data.preview.label}</b><span>{data.preview.role==="participant"?"Estás revisando el perfil real de este alumno.":"Como administrador puedes probar, editar y aprobar desde esta vista profesional."}</span></div><button onClick={()=>changePreview("admin")}>Volver a Administrador</button></div>}<div className="page-wrap">
      {data.viewer.role==="participant"
        ? <ParticipantArea data={data} screen={screen} setScreen={setScreen} act={act} panelConfig={panelConfig}/>
        : data.viewer.role==="professional"
          ? <ProfessionalArea data={data} screen={screen} setScreen={goScreen} open={open} act={act} selected={selected} setSelected={setSelected} panelEnabled={panelEnabled} panelConfig={panelConfig} onPanelConfigChange={setPanelConfig}/>
          : <AdminArea data={data} screen={screen} setScreen={goScreen} open={open} act={act} selected={selected} setSelected={setSelected} panelEnabled={panelEnabled} panelConfig={panelConfig} onPanelConfigChange={setPanelConfig}/>
      }
    </div><nav className="mobile-nav" aria-label="Secciones">{nav.map(x=><button key={x} className={screen===x?"active":""} onClick={()=>goScreen(x)}><span>{iconMap[x]}</span><small>{navShortLabel(x)}</small></button>)}</nav></main>
    {modal&&<Editor key={`${modal}-${String(context.id||"")}`} modal={modal} context={liveContext} data={data} close={()=>setModal(null)} act={act} nextNutrition={nextNutrition} reload={load} panelConfig={panelConfig}/>} {credentials&&<CredentialsDialog credentials={credentials} onClose={()=>setCredentials(null)}/>} {toast&&<div className="toast">✓ {toast}</div>} {error&&<div className="error-toast">{error}<button onClick={()=>setError("")}>×</button></div>}
  </div>
}

function CredentialsDialog({credentials,onClose}:{credentials:Exclude<Credentials,null>;onClose:()=>void}){
  const [copied,setCopied]=useState("");
  async function copy(value:string,label:string){try{await navigator.clipboard.writeText(value)}catch{const input=document.createElement("textarea");input.value=value;document.body.appendChild(input);input.select();document.execCommand("copy");input.remove()}setCopied(label);setTimeout(()=>setCopied(""),1800)}
  const whatsapp=`${credentials.password} es tu contraseña temporal de Proyecto 90 para ${credentials.email}. Ingresa en 90dias.habitofirme.app`;
  return <div className="modal-backdrop credentials-backdrop" onMouseDown={e=>e.target===e.currentTarget&&onClose()}><section className="editor-modal credentials-modal"><div className="modal-head"><div><span className="eyebrow">ACCESOS PROYECTO 90</span><h2>Contraseña temporal generada</h2></div><button onClick={onClose}>×</button></div><p className="modal-context">{credentials.emailed?"También la enviamos por correo a la cuenta indicada, por si necesita reenviarla.":"No se pudo enviar por correo; reenvíasela tú por WhatsApp."}</p><div className="credential-grid"><div className="credential-field"><span>Correo de acceso</span><div className="credential-value"><code>{credentials.email}</code><button className="secondary" onClick={()=>copy(credentials.email,"email")}>{copied==="email"?"✓ Copiado":"Copiar"}</button></div></div><div className="credential-field"><span>Contraseña temporal</span><div className="credential-value"><code>{credentials.password}</code><button className="primary" onClick={()=>copy(credentials.password,"password")}>{copied==="password"?"✓ Copiado":"Copiar"}</button></div></div></div><div className="credentials-actions"><button className="secondary" onClick={()=>copy(whatsapp,"whatsapp")}>{copied==="whatsapp"?"✓ Mensaje copiado":"Copiar mensaje para WhatsApp"}</button><button className="primary" onClick={onClose}>Listo</button></div><p className="credentials-note">Esta contraseña no se volverá a mostrar. Guárdala o envíala ahora; después puedes generar una nueva con «Restablecer acceso».</p></section></div>
}

function AdminArea({data,screen,setScreen,open,act,selected,setSelected,panelEnabled,panelConfig,onPanelConfigChange}:{data:AppData;screen:string;setScreen:(x:string)=>void;open:(m:Modal,r?:Row)=>void;act:(r:Row)=>Promise<unknown>;selected:string[];setSelected:(x:string[])=>void;panelEnabled:boolean;panelConfig:PanelConfig|null;onPanelConfigChange:(c:PanelConfig)=>void}){
  const people=data.participants||[]; const programs=data.programs||[];
  if(screen==="Participantes")return <ParticipantDirectory people={people} programs={programs} selected={selected} setSelected={setSelected} open={open} act={act} canEditBody={data.viewer.role==="admin"} panelConfig={panelConfig}/>;
  if(panelEnabled&&screen===PANEL_SCREEN&&panelConfig)return <WeeklyPanel viewerId={data.viewer.id} role={data.viewer.role} specialty={data.professionalSpecialty} config={panelConfig} onConfigChange={onPanelConfigChange}/>;
  if(screen==="Adherencia")return <><AdherencePanel people={people} records={data.habitDaily||[]} nutritionRecords={data.nutritionDaily||[]} outreach={data.adherenceOutreach||[]} act={act} panelConfig={panelConfig}/><DailyClosure people={people} records={data.habitDaily||[]} nutritionRecords={data.nutritionDaily||[]} habits={["training","macros"]} panelConfig={panelConfig}/></>;
  if(screen==="Seguimiento")return <ProfessionalTracking people={people} nutritionRecords={data.nutritionDaily||[]} habitRecords={data.habitDaily||[]} initialArea="nutrition" allowAreaSwitch notes={data.notes||[]} act={act} canPauseMacros canDeleteNotes macrosControls={(person)=><MacrosTrackingControls person={person} act={act}/>} panelConfig={panelConfig}/>;
  if(screen==="Profesionales")return <Professionals rows={data.professionals||[]} administrators={data.administrators||[]} viewerId={data.viewer.id} open={open} act={act}/>;
  if(screen==="Programas")return <ProgramManager data={data} open={open} act={act}/>;
  if(screen==="Nutrición")return <NutritionWorkspace people={people} open={open}/>;
  if(screen===TOOLS)return <ContentManager rows={data.content||[]} open={open}/>;
  if(screen==="Sesiones")return <SessionWorkspace sessions={data.sessions||[]} meetings={data.meetingRequests||[]} open={open} act={act} viewerId={data.viewer.id} viewerRole={data.viewer.role} viewerName={data.viewer.name}/>;
  if(screen==="Primer ingreso")return <IntakeConfig questions={data.intakeQuestions||[]} act={act}/>;
  const pendingNutrition=people.filter(x=>!x.nutrition_id).length; const noProgram=people.filter(x=>!x.program_id).length; const risk=countRiskyParticipants(data.habitDaily||[],data.nutritionDaily||[],people,panelConfig); const pendingMeetings=(data.meetingRequests||[]).filter(x=>x.status==="pending").length; const totalAttention=noProgram+pendingNutrition+risk+pendingMeetings;
  return <div className="command-dashboard"><section className="command-hero"><div><span className="eyebrow">CENTRO DE CONTROL · PROYECTO 90</span><h1>Hola, {first(data.viewer.name)}</h1><p>Tu prioridad es detectar dónde se está cayendo el proceso y actuar antes de que alguien abandone.</p></div><button className="primary" onClick={()=>open("participant")}>＋ Crear participante</button></section><section className="priority-board"><header><div><span className="eyebrow">REQUIERE ATENCIÓN HOY</span><h2>{totalAttention} {totalAttention===1?"acción pendiente":"acciones pendientes"}</h2></div><span className="priority-total">{totalAttention}</span></header><div className="priority-list"><button onClick={()=>setScreen("Participantes")}><i className="priority-icon training">↗</i><span><b>Alumnos sin programa</b><small>Necesitan una ruta de entrenamiento</small></span><strong>{noProgram}</strong></button><button onClick={()=>setScreen("Nutrición")}><i className="priority-icon nutrition">◒</i><span><b>Nutrición pendiente</b><small>Planes sin calcular o publicar</small></span><strong>{pendingNutrition}</strong></button><button onClick={()=>{setPanelFilterIntent("risk");setScreen("Adherencia")}}><i className="priority-icon risk">!</i><span><b>Adherencia en riesgo</b><small>Abre el panel semanal filtrado por riesgo</small></span><strong>{risk}</strong></button><button onClick={()=>setScreen("Sesiones")}><i className="priority-icon meeting">▣</i><span><b>Reuniones por confirmar</b><small>Solicitudes individuales pendientes</small></span><strong>{pendingMeetings}</strong></button></div></section><section className="pulse-strip"><Metric label="Participantes" value={String(people.length)} note="Registrados"/><Metric label="Activos" value={String(people.filter(x=>x.status==="active").length)} note="En recorrido" green/><Metric label="Con programa" value={String(people.length-noProgram)} note="Ruta asignada"/><Metric label="Planes listos" value={String(people.length-pendingNutrition)} note="Nutrición publicada"/></section><div className="section-heading"><div><span className="eyebrow">SEGUIMIENTO RECIENTE</span><h2>Participantes</h2></div></div><PeopleTable rows={people.slice(0,6)} selected={[]} setSelected={()=>{}} open={open}/></div>
}

function ProfessionalArea({data,screen,setScreen,open,act,selected,setSelected,panelEnabled,panelConfig,onPanelConfigChange}:{data:AppData;screen:string;setScreen:(x:string)=>void;open:(m:Modal,r?:Row)=>void;act:(r:Row)=>Promise<unknown>;selected:string[];setSelected:(x:string[])=>void;panelEnabled:boolean;panelConfig:PanelConfig|null;onPanelConfigChange?:(c:PanelConfig)=>void}){
  const people=data.participants||[]; const programs=data.programs||[]; const nutrition=data.professionalSpecialty==="nutrition";
  const alerts=computeAdherenceAlerts(people,data.habitDaily||[],data.nutritionDaily||[],nutrition?["macros"]:["training"],panelConfig);
  if(panelEnabled&&screen===PANEL_SCREEN&&panelConfig)return <WeeklyPanel viewerId={data.viewer.id} role={data.viewer.role} specialty={data.professionalSpecialty} config={panelConfig} onConfigChange={onPanelConfigChange}/>;
  if(screen==="Seguimiento")return <><AdherencePanel people={people} records={data.habitDaily||[]} nutritionRecords={data.nutritionDaily||[]} outreach={data.adherenceOutreach||[]} act={act} mode={nutrition?"macros":"training"} canEditCells={false} canMarkContact panelConfig={panelConfig}/><DailyClosure people={people} records={data.habitDaily||[]} nutritionRecords={data.nutritionDaily||[]} habits={nutrition?["macros"]:["training"]} panelConfig={panelConfig}/><div className="section-heading"><div><span className="eyebrow">DETALLE POR ALUMNO</span><h2>Cumplimiento individual</h2></div></div><ProfessionalTracking people={people} nutritionRecords={data.nutritionDaily||[]} habitRecords={data.habitDaily||[]} initialArea={nutrition?"nutrition":"training"} notes={data.notes||[]} act={act} canPauseMacros={nutrition} macrosControls={(person)=><MacrosTrackingControls person={person} act={act}/>} panelConfig={panelConfig}/></>;
  if(screen==="Participantes")return <ParticipantDirectory people={people} programs={programs} selected={selected} setSelected={setSelected} open={open} act={act} canCreate={false} canAssignProgram={!nutrition} profileModal="professional-student" panelConfig={panelConfig}/>;
  if(screen==="Programas")return <ProgramManager data={data} open={open} act={act}/>;
  if(screen==="Sesiones"&&!nutrition)return <SessionWorkspace sessions={data.sessions||[]} meetings={[]} open={open} act={act} showMeetings={false} viewerId={data.viewer.id} viewerRole={data.viewer.role} viewerName={data.viewer.name}/>;
  if(screen==="Nutrición")return <NutritionWorkspace people={people} open={open} profileModal="professional-student"/>;
  if(screen===TOOLS)return <ContentManager rows={data.content||[]} open={open}/>;
  const pending=nutrition?people.filter(x=>!x.nutrition_id||x.nutrition_status!=="approved"):people.filter(x=>!x.program_id||x.training_approval_status!=="approved"); const ready=people.length-pending.length;
  return <div className="professional-dashboard"><section className="professional-hero"><div className="professional-symbol">{nutrition?"◒":"↗"}</div><div><span className="eyebrow">{nutrition?"ESPACIO DE NUTRICIÓN":"ESPACIO DE ENTRENAMIENTO"}</span><h1>{nutrition?"Decisiones claras para la vida real":"Entrenamiento seguro, claro y progresivo"}</h1><p>{nutrition?"Revisa los antecedentes, calcula los requerimientos y publica planes que cada alumno pueda comprender.":"Revisa el contexto de cada alumno, asigna la ruta correcta y aprueba lo que recibirá."}</p></div></section><section className="professional-focus"><div><span className="eyebrow">TU COLA DE APROBACIÓN</span><h2>{pending.length} {pending.length===1?"persona requiere":"personas requieren"} revisión</h2><p>{nutrition?"Abre cada ficha, revisa macros y respuestas, y aprueba el plan.":"Abre cada ficha, revisa la rutina y respuestas, y aprueba la asignación."}</p></div><div className="focus-count"><strong>{pending.length}</strong><span>pendientes</span></div></section><section className="professional-summary"><Metric label="Participantes" value={String(people.length)} note="En seguimiento"/><Metric label={nutrition?"Planes aprobados":"Rutinas aprobadas"} value={String(ready)} note="Revisión completa" green/><Metric label="Por aprobar" value={String(pending.length)} note="Prioridad actual"/><Metric label="En riesgo" value={String(alerts.riskCount)} note={nutrition?`Macros en rojo ${alerts.streakNeeded} días`:`Entreno en rojo ${alerts.streakNeeded} días`}/><Metric label="Falta reportar" value={String(alerts.missingCount)} note={`Sin registro ≥ ${alerts.missingCutoffDays} d`}/></section><div className="section-heading"><div><span className="eyebrow">ALERTAS DE ESTA SEMANA</span><h2>{alerts.total===0?"Sin alertas operativas":`${alerts.total} ${alerts.total===1?"alumno necesita":"alumnos necesitan"} seguimiento`}</h2></div><button className="secondary" onClick={()=>{setPanelFilterIntent("all");setScreen("Seguimiento")}}>Abrir seguimiento →</button></div><div className="section-heading"><div><span className="eyebrow">PRIORIDAD ACTUAL</span><h2>{nutrition?"Planes por aprobar":"Rutinas por aprobar"}</h2></div><button className="secondary" onClick={()=>setScreen(nutrition?"Nutrición":"Participantes")}>Ver todos los alumnos →</button></div><section className="professional-queue">{pending.slice(0,6).map(person=>{const name=`${person.first_name||""} ${person.last_name||""}`.trim()||String(person.email);return <button key={String(person.id)} onClick={()=>open("professional-student",person)}><span className="avatar">{initials(name)}</span><span><b>{name}</b><small>{nutrition?(person.nutrition_id?"Plan listo para revisar":"Plan sin calcular"):(person.program_id?"Rutina pendiente de aprobación":"Sin rutina asignada")}</small></span><strong>Abrir ficha →</strong></button>})}{pending.length===0&&<div className="professional-empty"><span>✓</span><div><b>Todo aprobado</b><p>No hay alumnos pendientes de revisión.</p></div></div>}</section></div>
}

function Professionals({rows,administrators,viewerId,open,act}:{rows:Row[];administrators:Row[];viewerId:string;open:(m:Modal,r?:Row)=>void;act:(r:Row)=>Promise<unknown>}){return <><Title eyebrow="EQUIPO PROYECTO 90" title="Profesionales y administradores" copy="Administra quién puede operar la plataforma y qué especialidad tiene cada profesional." action={<div className="inline-actions"><button className="secondary" onClick={()=>open("admin")}>＋ Administrador</button><button className="primary" onClick={()=>open("professional")}>＋ Profesional</button></div>}/><div className="access-system-note"><span>⌁</span><div><b>Acceso actual de Proyecto 90</b><p>El correo queda autorizado aquí. La autenticación sigue protegida por la cuenta de acceso asociada; una contraseña propia requiere integrar el proveedor de identidad que configurará el programador.</p></div></div><div className="section-heading"><div><span className="eyebrow">GESTIÓN TOTAL</span><h2>Administradores</h2></div><span>{administrators.length} perfiles</span></div><section className="team-management-grid">{administrators.map(x=><article key={String(x.id)}><span className="avatar">{initials(`${x.first_name||""} ${x.last_name||""}`)}</span><div><h3>{`${x.first_name||""} ${x.last_name||""}`.trim()||String(x.email)}</h3><p>{String(x.email)}</p></div><span className="audience both">Administrador</span><div className="team-actions"><button className="secondary" onClick={()=>open("admin-edit",x)}>Editar</button><button className="secondary" onClick={()=>confirm("¿Generar una nueva contraseña temporal y enviarla por correo a este administrador?")&&act({action:"credentials.resend",id:x.id})}>Restablecer acceso</button>{String(x.id)!==viewerId&&<button className="danger-link" onClick={()=>confirm("¿Eliminar este administrador?")&&act({action:"admin.delete",id:x.id})}>Eliminar</button>}</div></article>)}</section><div className="section-heading"><div><span className="eyebrow">EQUIPO ESPECIALISTA</span><h2>Coach y Nutrición</h2></div><span>{rows.length} perfiles</span></div>{rows.length===0?<Empty title="Aún no hay profesionales" copy="Agrega al coach y a la nutricionista con el correo que usarán para ingresar." action={<button className="primary" onClick={()=>open("professional")}>Crear profesional</button>}/>:<section className="team-management-grid">{rows.map(x=><article key={String(x.id)}><span className="avatar">{initials(`${x.first_name||""} ${x.last_name||""}`)}</span><div><h3>{`${x.first_name||""} ${x.last_name||""}`.trim()||String(x.email)}</h3><p>{String(x.email)}</p></div><span className={`audience ${x.specialty==="nutrition"?"nutrition":"coach"}`}>{x.specialty==="nutrition"?"Nutricionista":"Coach"}</span><div className="team-actions"><button className="secondary" onClick={()=>open("professional-edit",x)}>Editar</button><button className="secondary" onClick={()=>confirm("¿Generar una nueva contraseña temporal y enviarla por correo a este profesional?")&&act({action:"credentials.resend",id:x.id})}>Restablecer acceso</button><button className="danger-link" onClick={()=>confirm("¿Eliminar este profesional? Esta acción no elimina alumnos ni planes.")&&act({action:"professional.delete",id:x.id})}>Eliminar</button></div></article>)}</section>}</>}

function PeopleTable({rows,selected,setSelected,open}:{rows:Row[];selected:string[];setSelected:(x:string[])=>void;open:(m:Modal,r?:Row)=>void}){return <div className="table-card"><table><thead><tr><th><input type="checkbox" aria-label="Seleccionar todos" checked={rows.length>0&&selected.length===rows.length} onChange={e=>setSelected(e.target.checked?rows.map(x=>String(x.id)):[])}/></th><th>Participante</th><th>Estado</th><th>Entrenamiento</th><th>Nutrición</th><th>Adherencia</th><th></th></tr></thead><tbody>{rows.map(p=><tr key={String(p.id)}><td><input type="checkbox" checked={selected.includes(String(p.id))} onChange={e=>setSelected(e.target.checked?[...selected,String(p.id)]:selected.filter(x=>x!==p.id))}/></td><td><div className="person"><span className="avatar">{initials(`${p.first_name||""} ${p.last_name||""}`)}</span><div><b>{`${p.first_name||""} ${p.last_name||""}`.trim()||String(p.email)}</b><small>{String(p.email)}</small></div></div></td><td><Status text={String(p.status||"invited")}/></td><td>{p.program_name?String(p.program_name):<span className="muted">Sin asignar</span>}</td><td>{p.nutrition_id?<Status text="Listo"/>:<Status text="Pendiente"/>}</td><td>{p.adherence==null||Number(p.adherence_elapsed_days||1)===0?<span className="muted">Sin iniciar</span>:<b className={Number(p.adherence)<40?"red-text":"green-text"}>{String(p.adherence)}%</b>}</td><td><div className="row-actions"><button className="row-action" onClick={()=>open("intake-view",p)}>Ficha</button><button className="row-action" onClick={()=>open("participant-edit",p)}>Editar ›</button></div></td></tr>)}</tbody></table></div>}

function ProgramManager({data,open,act}:{data:AppData;open:(m:Modal,r?:Row)=>void;act:(r:Row)=>Promise<unknown>}){
  const programs=data.programs||[],exercises=data.exercises||[];
  const [active,setActive]=useState(String(programs[0]?.id||""));
  const program=programs.find(x=>String(x.id)===active)||programs[0];
  const guide=(data.programGuides||[]).find(x=>String(x.program_id)===String(program?.id));
  const workouts=(data.workouts||[]).filter(x=>String(x.program_id)===String(program?.id));
  const links=data.workoutExercises||[];
  return <><Title eyebrow="RUTAS DE ENTRENAMIENTO" title="Programas y rutinas" copy="Coach y administración pueden crear rutas y editar cada ejercicio. Los cambios se reflejan en la rutina asignada." action={<button className="primary" onClick={()=>open("program")}>＋ Crear rutina</button>}/>
    <div className="program-tabs">{programs.map(p=><button className={String(p.id)===String(program?.id)?"active":""} key={String(p.id)} onClick={()=>setActive(String(p.id))}><b>{String(p.name)}</b><small>{(data.programGuides||[]).some(g=>String(g.program_id)===String(p.id))?"Rutina base editable":`${String(p.workout_count||0)} días`} · {String(p.participant_count||0)} alumnos</small></button>)}</div>
    {guide?<><RoutineGuide guideRow={guide} exercises={exercises} admin openExercise={row=>open("exercise-edit",row)} act={act}/><GuideEditor guideRow={guide} exercises={exercises} act={act}/></>:program&&<><div className="section-heading"><div><span className="eyebrow">{String(program.level)} · {String(program.location)}</span><h2>{String(program.name)}</h2></div><div className="inline-actions"><button className="secondary" onClick={()=>open("exercise")}>＋ Ejercicio / video</button><button className="primary" onClick={()=>open("workout",program)}>＋ Agregar día</button></div></div>{workouts.length===0?<Empty title="Aún no hay días de entrenamiento" copy="Crea el primer día y luego agrega ejercicios desde la biblioteca." action={<button className="primary" onClick={()=>open("workout",program)}>Crear primer día</button>}/>:<section className="workout-admin-grid">{workouts.map(w=><article className="workout-admin" key={String(w.id)}><div className="workout-head"><div><span className="eyebrow">MES {String(w.month)} · SEMANA {String(w.week)}</span><h3>{String(w.name)}</h3></div><div className="inline-actions"><button className="quiet-edit" onClick={()=>open("workout-edit",w)}>Editar</button><button className="secondary" onClick={()=>open("attach",w)}>＋ Ejercicio</button></div></div>{links.filter(x=>String(x.workout_id)===String(w.id)).map((x,i)=><div className="admin-exercise-row" key={String(x.id)}><span>{i+1}</span><div><b>{String(x.exercise_name)}</b><small>{String(x.sets)} × {String(x.reps)} · {String(x.rest_seconds)}s descanso</small></div>{Boolean(x.youtube_url)&&<a href={String(x.youtube_url)} target="_blank" rel="noreferrer">Video ↗</a>}<button className="quiet-edit" onClick={()=>open("attach-edit",x)}>Editar</button><button className="danger-link" onClick={()=>confirm("¿Retirar este ejercicio de la rutina?")&&act({action:"workout.exercise.remove",id:x.id})}>Retirar</button></div>)}</article>)}</section>}</>}
    <div className="section-heading"><div><span className="eyebrow">VIDEOS TÉCNICOS</span><h2>Biblioteca de ejercicios</h2></div><button className="secondary" onClick={()=>open("exercise")}>＋ Nuevo ejercicio</button></div>{exercises.length===0?<Empty title="Biblioteca vacía" copy="Agrega ejercicios con su video técnico."/>:<section className="exercise-library compact-library">{exercises.map(x=><article key={String(x.id)}><span className="icon-tile">▶</span><div><h3>{String(x.name)}</h3><p>{String(x.category||"Sin categoría")} · {x.youtube_url?"Con video":"Video pendiente"}</p></div><button className="secondary" onClick={()=>open("exercise-edit",x)}>Editar</button></article>)}</section>}</>;
}

function ContentManager({rows,open}:{rows:Row[];open:(m:Modal,r?:Row)=>void}){return <><Title eyebrow="BIBLIOTECA CENTRAL" title="Contenido" copy="Publica aprendizaje, PDFs y videos para que aparezcan en la sección Contenido/Herramientas del alumno." action={<button className="primary" onClick={()=>open("content")}>＋ Nuevo contenido</button>}/>{rows.length===0?<Empty title="Aún no hay contenido" copy="Publica el primer módulo de hábitos, nutrición o entrenamiento." action={<button className="primary" onClick={()=>open("content")}>Publicar contenido</button>}/>:<section className="content-table panel">{rows.map(x=><div className="content-row" key={String(x.id)}><span className="icon-tile">{String(x.file_kind||"")==="pdf"?"PDF":"▶"}</span><div><h3>{String(x.title)}</h3><p>{String(x.category)} · {String(x.description||"")}</p>{Boolean(x.file_key||x.file_kind)&&<p className="content-file-meta">{String(x.file_kind||"archivo")}{x.file_key?" · archivo cargado":""}</p>}</div>{Boolean(x.video_url)&&<a href={String(x.video_url)} target="_blank" rel="noreferrer">Ver video ↗</a>}{Boolean(x.file_key)&&String(x.file_kind||"")==="pdf"&&<button className="secondary" onClick={()=>openPdf(String(x.file_key))}>Abrir PDF</button>}<Status text="Publicado"/></div>)}</section>}</>}
function ParticipantArea({data,screen,setScreen,act,panelConfig}:{data:AppData;screen:string;setScreen:(x:string)=>void;act:(r:Row)=>Promise<unknown>;panelConfig:PanelConfig|null}){if(!data.profile?.completed_at)return <IntakeForm questions={data.intakeQuestions||[]} responses={data.intakeResponses||[]} act={act}/>;const programs=data.programs||[];const primaryProgram=programs.find(x=>x.kind!=="emergency")||programs[0];const emergencyProgram=programs.find(x=>x.kind==="emergency");const guideFor=(program?:Row)=>program?(data.programGuides||[]).find(x=>String(x.program_id)===String(program.id)):undefined;const program=primaryProgram;const guide=guideFor(primaryProgram);const emergencyGuide=guideFor(emergencyProgram);const workouts=data.workouts||[];const nutrition=data.nutrition;const guidePdfKey=String(data.nutritionGuidePdf||nutrition?.pdf_key||"");const links=data.workoutExercises||[];const adherence=Number(data.metrics?.[0]?.adherence||0);const profileStart=data.profile?.challenge_start;const challengeStart=profileStart||program?.assigned_at;const awaitingApproval=!profileStart;const startMs=challengeStart?new Date(`${String(challengeStart).slice(0,10)}T12:00:00Z`).getTime():appNow;const daysSince=Math.floor((appNow-startMs)/86400000);const currentDay=challengeStart?(daysSince<0?0:Math.max(1,Math.min((panelConfig?.challenge_length_days??PANEL_CONFIG_DEFAULTS.challenge_length_days),daysSince+1))):0;const progress=Math.round(currentDay/(panelConfig?.challenge_length_days??PANEL_CONFIG_DEFAULTS.challenge_length_days)*100);const waitingStart=currentDay===0&&Boolean(challengeStart);const macrosDeferred=String(data.profile?.macros_tracking||"")==="deferred"||data.macrosVisible===false;const trainingAdherence=Number(data.adherence?.training_pct??adherence);const macrosAdherence=Number(data.adherence?.macros_pct??0);const waterAdherence=Number(data.adherence?.water_pct??0);const weights=panelConfig?.habit_weights;const wTrain=weights?.training??PANEL_CONFIG_DEFAULTS.habit_weights.training,wMacro=weights?.macros??PANEL_CONFIG_DEFAULTS.habit_weights.macros,wWater=weights?.water??PANEL_CONFIG_DEFAULTS.habit_weights.water;const wSum=wTrain+wMacro+wWater||1;const equalAs=panelConfig?.adherence_equal_weights_as_40_40_20??PANEL_CONFIG_DEFAULTS.adherence_equal_weights_as_40_40_20;const nTrain=equalAs&&wTrain===wMacro&&wMacro===wWater?0.4:wTrain/wSum;const nMacro=equalAs&&wTrain===wMacro&&wMacro===wWater?0.4:wMacro/wSum;const nWater=equalAs&&wTrain===wMacro&&wMacro===wWater?0.2:wWater/wSum;const totalAdherence=Number(data.adherence?.adherence??Math.round(trainingAdherence*nTrain+macrosAdherence*nMacro+waterAdherence*nWater));const formulaNote=habitWeightsFormulaText(weights,panelConfig?.adherence_equal_weights_as_40_40_20);if(screen==="Entrenamiento"&&(guide||emergencyGuide))return <ParticipantTraining guide={guide} emergencyGuide={emergencyGuide} exercises={data.exercises||[]}/>;if(screen==="Entrenamiento")return <><Title eyebrow="TU RUTA ASIGNADA" title={program?String(program.name):"Entrenamiento pendiente"} copy={program?"Abre una sesión por vez y revisa cada bloque antes de comenzar.":"El equipo todavía no te asigna un programa."}/>{!program?<Empty title="Estamos preparando tu ruta" copy="Te avisaremos cuando tu programa esté asignado."/>:<section className="workout-user-grid">{workouts.map(w=><article className="workout-user" key={String(w.id)}><span className="eyebrow">MES {String(w.month)} · SEMANA {String(w.week)}</span><h2>{String(w.name)}</h2>{links.filter(x=>String(x.workout_id)===String(w.id)).map((x,i)=><div className="exercise-row" key={String(x.id)}><span className="number">{i+1}</span><div><h3>{String(x.exercise_name)}</h3><p>{String(x.sets)} × {String(x.reps)} · {String(x.rest_seconds)}s descanso</p></div>{Boolean(x.youtube_url)&&<a className="secondary" href={String(x.youtube_url)} target="_blank" rel="noreferrer">Ver técnica ▶</a>}</div>)}</article>)}</section>}</>;
if(screen==="Alimentación")return <><Title eyebrow="TU PLAN PERSONAL" title="Mi alimentación" copy="Objetivos aprobados y registro diario de tus resultados."/>{macrosDeferred?<div className="macros-deferred-banner"><b>Macros en pausa</b><p>Tu nutricionista pausó el seguimiento de macros por ahora. Sigue las indicaciones de tu plan; el registro diario se reactivará cuando lo liberen.</p></div>:null}{nutrition?<>{!macrosDeferred&&<section className="macro-grid"><Metric label="Calorías" value={`${nutrition.calories||0}`} note="kcal / día"/><Metric label="Proteínas" value={`${nutrition.protein||0} g`} note="Objetivo diario" green/><Metric label="Carbohidratos" value={`${nutrition.carbs||0} g`} note="Objetivo diario"/><Metric label="Grasas" value={`${nutrition.fats||0} g`} note="Objetivo diario"/></section>}<article className="panel plan-view"><div><h3>Tu plan nutricional</h3><p>{String(nutrition.notes||"Revisa tu guía y aplica los objetivos de manera flexible.")}</p></div>{guidePdfKey&&<button className="primary" onClick={()=>openPdf(guidePdfKey)}>Ver guía nutricional (PDF)</button>}</article></>:guidePdfKey?<article className="panel plan-view"><div><h3>Guía nutricional</h3><p>Abre el PDF con tus indicaciones de alimentación de Proyecto 90 Días.</p></div><button className="primary" onClick={()=>openPdf(guidePdfKey)}>Ver guía nutricional (PDF)</button></article>:<Empty title="Plan en preparación" copy="Tu nutricionista aún no ha publicado tus objetivos."/>}{macrosDeferred?null:<NutritionDailyTracker records={data.nutritionDaily||[]} plan={nutrition} startDate={data.profile?.challenge_start||program?.assigned_at||data.profile?.created_at} act={act} panelConfig={panelConfig}/>}</>;
if(screen===TOOLS){const library=data.content||[];const contentItems=guidePdfKey&&!library.some(x=>String(x.file_key||"")===guidePdfKey)?[{id:"nutrition-guide",title:"Guía nutricional",description:"PDF de tu plan nutricional personalizado.",category:"Nutrición",file_key:guidePdfKey,file_kind:"pdf"} as Row,...library]:library;return <><Title eyebrow="APRENDER PARA NO DEPENDER" title={TOOLS} copy="Links, PDFs, videos y herramientas publicados por tu equipo."/>{contentItems.length===0?<Empty title="Próximamente" copy="Los módulos aparecerán aquí cuando sean publicados."/>:<section className="learning-grid">{contentItems.map(x=><article className="learn-card" key={String(x.id)}><span className="learn-cover">{String(x.file_kind||"")==="pdf"?"PDF":"▶"}</span><div><span className="tag">{String(x.category)}</span><h3>{String(x.title)}</h3><p>{String(x.description||"")}</p>{Boolean(x.video_url)&&<a href={String(x.video_url)} target="_blank" rel="noreferrer">Ver contenido →</a>}{Boolean(x.file_key)&&String(x.file_kind||"")==="pdf"&&<button className="secondary" onClick={()=>openPdf(String(x.file_key))}>Abrir PDF</button>}{Boolean(x.file_key)&&String(x.file_kind||"")!=="pdf"&&String(x.file_kind||"")!=="video"&&<button className="secondary" onClick={()=>openPdf(String(x.file_key))}>Abrir archivo</button>}</div></article>)}</section>}</>;}
if(screen==="Progreso")return <><Title eyebrow="TU HISTORIA" title="Progreso" copy={`Adherencia y checkpoints de tus ${panelConfig?.challenge_length_days??PANEL_CONFIG_DEFAULTS.challenge_length_days} días.`}/><section className="stats-grid four"><Metric label="Entrenamientos" value={`${trainingAdherence}%`} note="✓ sobre días transcurridos" green/><Metric label="Macros" value={`${macrosAdherence}%`} note="Días dentro de tus objetivos"/><Metric label="Agua" value={`${Number(data.adherence?.water_pct||0)}%`} note="✓ sobre días transcurridos"/><Metric label="Adherencia total" value={`${Number(data.adherence?.adherence||0)}%`} note={formulaNote}/></section><ParticipantHabitMatrix records={data.habitDaily||[]} nutritionRecords={data.nutritionDaily||[]} plan={nutrition} startDate={data.profile?.challenge_start||program?.assigned_at||data.profile?.created_at} act={act} panelConfig={panelConfig}/></>;
if(screen==="Comentarios")return <><Title eyebrow="MENSAJES DEL EQUIPO" title="Comentarios" copy="Observaciones de coach y nutrición. Es solo lectura: no es un chat."/><ParticipantNotesList notes={data.notes||[]}/></>;
if(screen==="Mi Semana")return <ParticipantWeekOverview guideRow={guide} program={program} workouts={workouts} sessions={data.sessions||[]} startDate={data.profile?.challenge_start||program?.assigned_at||data.profile?.created_at} onOpenTraining={()=>setScreen("Entrenamiento")} panelConfig={panelConfig}><MeetingRequest meetings={data.meetingRequests||[]} act={act}/></ParticipantWeekOverview>;
return <div className="participant-home"><section className="journey-hero"><div><span className="eyebrow">TU PROYECTO 90</span><h1>Hola, {first(data.viewer.name)}</h1><p>{awaitingApproval?"Tu desafío inicia cuando coach y nutri aprueben tu plan":waitingStart?`Tu desafío comienza el ${new Date(`${String(challengeStart).slice(0,10)}T12:00:00Z`).toLocaleDateString("es-CL",{day:"numeric",month:"long",year:"numeric",timeZone:"UTC"})}. Mientras tanto puedes completar tu ficha y revisar el contenido.`:"No tienes que hacerlo perfecto. Hoy solo tienes que seguir apareciendo."}</p></div><div className="journey-day"><span>{awaitingApproval||waitingStart?"INICIA":"DÍA"}</span><strong>{awaitingApproval||waitingStart?"—":currentDay}</strong><small>{awaitingApproval?"EN REVISIÓN":waitingStart?"PRONTO":`DE ${panelConfig?.challenge_length_days??PANEL_CONFIG_DEFAULTS.challenge_length_days}`}</small></div><div className="journey-track"><i style={{width:`${progress}%`}}/><span>Inicio</span><b>{progress}% del recorrido</b><span>Día {panelConfig?.challenge_length_days??PANEL_CONFIG_DEFAULTS.challenge_length_days}</span></div></section><NoticesPanel notices={data.notices||[]} act={act}/><ProgressMilestones person={{...(data.profile||{}),...(data.adherence||{})}} checkpoints={data.checkpoints||[]} currentDay={currentDay} editable={!data.preview} act={act} panelConfig={panelConfig}/><section className="today-command"><header><div><span className="eyebrow">HOY · UNA ACCIÓN A LA VEZ</span><h2>¿Qué hago ahora?</h2></div><span className="today-date">{appToday.toLocaleDateString("es-CL",{weekday:"long",day:"numeric",month:"long"})}</span></header><div className="today-actions"><article className="today-primary"><span className="today-number">01</span><div><small>ENTRENAMIENTO</small><h3>{workouts[0]?String(workouts[0].name):"Tu ruta está en preparación"}</h3><p>{program?String(program.name):"El equipo te asignará un programa."}</p></div><button className="primary" onClick={()=>setScreen("Entrenamiento")}>{program?"Abrir mi entrenamiento":"Ver estado"} →</button></article><article><span className="today-number">02</span><div><small>ALIMENTACIÓN</small><h3>{nutrition?`${nutrition.calories||0} kcal · ${nutrition.protein||0} g proteína`:"Plan en preparación"}</h3><p>{nutrition?"Tus objetivos diarios están aprobados.":"La nutricionista está revisando tu información."}</p></div><button className="secondary" onClick={()=>setScreen("Alimentación")}>Ver mi plan →</button></article></div></section><section className="home-lower"><article className="adherence-story"><header><div><span className="eyebrow">ADHERENCIA</span><h2>Tu constancia, sin castigos</h2></div><strong>{totalAdherence}%</strong></header><p>El número no te juzga. Nos ayuda a detectar dónde necesitas apoyo para volver al plan.</p><div className="adherence-row"><span>Entrenamiento</span><i><b style={{width:`${trainingAdherence}%`}}/></i><strong>{trainingAdherence}%</strong></div><div className="adherence-row"><span>Macros</span><i><b style={{width:`${macrosAdherence}%`}}/></i><strong>{macrosAdherence}%</strong></div><div className="adherence-row"><span>Agua</span><i><b style={{width:`${waterAdherence}%`}}/></i><strong>{waterAdherence}%</strong></div><button className="text-action" onClick={()=>setScreen("Progreso")}>Ver mi progreso completo →</button></article><article className="support-card"><span className="eyebrow">ACOMPAÑAMIENTO</span><h2>{data.sessions?.[0]?String(data.sessions[0].title):"Tu equipo está contigo"}</h2><p>{data.sessions?.[0]?new Date(String(data.sessions[0].starts_at)).toLocaleString("es-CL"):"Las próximas sesiones y apoyos aparecerán aquí."}</p><button className="secondary" onClick={()=>setScreen("Mi Semana")}>Ver mi semana →</button></article></section></div>}

function chileTodayIso(){return new Intl.DateTimeFormat("en-CA",{timeZone:"America/Santiago",year:"numeric",month:"2-digit",day:"2-digit"}).format(new Date())}

function Editor({modal,context,data,close,act,nextNutrition,reload,panelConfig}:{modal:Exclude<Modal,null>;context:Row;data:AppData;close:()=>void;act:(x:Row)=>Promise<unknown>;nextNutrition:(id:string)=>void;reload?:()=>unknown;panelConfig:PanelConfig|null}){const [saving,setSaving]=useState(false);const [fileKey,setFileKey]=useState(String(context.pdf_key||context.file_key||""));const [uploading,setUploading]=useState(false);const [pendingFile,setPendingFile]=useState<File|null>(null);const [uploadError,setUploadError]=useState("");const [uploadProgress,setUploadProgress]=useState("");const [uploadedName,setUploadedName]=useState("");const uploadRef=useRef<Promise<string>|null>(null);useEffect(()=>{setFileKey(String(context.pdf_key||context.file_key||""));setPendingFile(null);setUploadError("");setUploadedName("")},[context.id,context.pdf_key,context.file_key]);if(modal==="professional-student")return <ProfessionalStudentFile context={context} data={data} close={close} act={act} panelConfig={panelConfig}/>;if(modal==="participant-body")return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&close()}><section className="editor-modal response-modal"><div className="modal-head"><div><span className="eyebrow">CORRECCIÓN ADMINISTRADOR</span><h2>Editar datos · {`${context.first_name||""} ${context.last_name||""}`.trim()||String(context.email||"Alumno")}</h2></div><button onClick={close}>×</button></div>{data.viewer.role==="admin"?<BodyDataEditor person={context} questions={data.intakeQuestions||[]} act={act} startOpen panelConfig={panelConfig}/>:<p className="modal-context">Solo el administrador puede corregir estos datos.</p>}<ProgressMilestones person={context} currentDay={dayOf90(context,panelConfig?.challenge_length_days)} panelConfig={panelConfig}/><div className="editor-actions body-modal-actions"><button type="button" className="secondary" onClick={close}>Cerrar</button></div></section></div>;if(modal==="intake-view")return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&close()}><section className="editor-modal response-modal"><div className="modal-head"><div><span className="eyebrow">FICHA DEL ALUMNO</span><h2>Formulario y seguimiento</h2></div><button onClick={close}>×</button></div><div className="participant-file-summary"><span><small>Día actual</small><b>{dayOf90(context,panelConfig?.challenge_length_days)===0?"Sin iniciar":`${dayOf90(context,panelConfig?.challenge_length_days)}/${panelConfig?.challenge_length_days??PANEL_CONFIG_DEFAULTS.challenge_length_days}`}</b></span><span><small>Peso inicial</small><b>{context.weight?`${context.weight} kg`:"No informado"}</b></span><span><small>Estatura</small><b>{formatHeightCm(context.height,"No informado")}</b></span><span><small>Último peso</small><b>{context.latest_weight?`${context.latest_weight} kg`:"No informado"}</b></span><span><small>Programa</small><b>{String(context.program_name||"Sin asignar")}</b></span></div>{data.viewer.role==="admin"&&<StartChallengeEditor context={context} act={act}/>}{data.viewer.role==="admin"&&<BodyDataEditor person={context} questions={data.intakeQuestions||[]} act={act} panelConfig={panelConfig}/>}<ProgressMilestones person={context} currentDay={dayOf90(context,panelConfig?.challenge_length_days)} panelConfig={panelConfig}/><MacrosTrackingControls person={context} act={act}/><StaffNotesPanel notes={data.notes||[]} userId={String(context.id)} act={act} canDelete={data.viewer.role==="admin"}/><IntakeResponses participant={context} questions={data.intakeQuestions||[]} responses={data.intakeResponses||[]}/></section></div>;async function submit(e:FormEvent<HTMLFormElement>){e.preventDefault();setSaving(true);const form=new FormData(e.currentTarget);const values=Object.fromEntries(form.entries());let savedFileKey=fileKey;if(modal==="nutrition"||modal==="content"){try{if(uploadRef.current)savedFileKey=await uploadRef.current;else if(pendingFile)savedFileKey=await startUpload(pendingFile)}catch(error){setSaving(false);alert(`No se guardó: ${error instanceof Error?error.message:"no fue posible subir el archivo"}`);return}}const editing=["participant-edit","professional-edit","admin-edit","workout-edit","exercise-edit","attach-edit"].includes(modal)||(modal==="session"&&Boolean(context.id))||modal==="meeting-review";const action=modal==="session"&&context.id?"session.update":actionFor(modal);try{const pros=data.professionals||[];const selectedPro=pros.find(row=>String(row.id)===String(values.professionalId));const professionalName=selectedPro?`${selectedPro.first_name||""} ${selectedPro.last_name||""}`.trim()||String(selectedPro.email||""):String(values.professional||context.professional||"");await act({...values,action,...(editing?{id:context.id}:{}) ,...(modal==="workout"?{programId:context.id}:{}),...(modal==="attach"?{workoutId:context.id}:{}),...(modal==="nutrition"?{userId:context.id,pdfKey:savedFileKey,effectiveFrom:String(values.effectiveFrom||chileTodayIso())}:{}),...(modal==="content"?{fileKey:savedFileKey,fileKind:values.fileKind||"link"}:{}),...(modal==="session"?{professionalId:values.professionalId||"",professional:professionalName}:{})});if(modal==="nutrition")nextNutrition(String(context.id));else close()}finally{setSaving(false)}}function startUpload(file:File):Promise<string>{setUploading(true);setUploadError("");setUploadProgress("");const fields:Record<string,string>=modal==="content"?{purpose:"content"}:{userId:String(context.id)};const task=(async()=>{try{const j=await uploadFile({file,url:apiUrl("/api/files"),headers:authHeaders(),fields,onProgress:(done,total)=>setUploadProgress(total>1?` ${Math.round(done/total*100)}%`:"")});setFileKey(j.key);setUploadedName(String(j.name||file.name));setPendingFile(null);if(modal!=="content"&&reload)void reload();if(j.fileKind&&modal==="content"){const kindInput=document.querySelector('select[name="fileKind"]') as HTMLSelectElement|null;if(kindInput)kindInput.value=String(j.fileKind)}return j.key}catch(error){setUploadError(error instanceof Error?error.message:"No fue posible subir el archivo");throw error}finally{setUploading(false)}})();uploadRef.current=task;void task.catch(()=>undefined).finally(()=>{if(uploadRef.current===task)uploadRef.current=null});return task}function pickFile(file?:File|null){if(!file)return;setPendingFile(file);void startUpload(file).catch(()=>undefined)}const uploadStatus=(done:string,empty:string)=>uploading?`Subiendo ${pendingFile?.name||"archivo"}…${uploadProgress}`:pendingFile?`Seleccionado: ${pendingFile.name} · se subirá al pulsar Guardar`:fileKey?done:empty;return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)close()}}><section className="editor-modal"><div className="modal-head"><div><span className="eyebrow">EDITOR PROYECTO 90</span><h2>{modalTitle(modal,context)}</h2></div><button onClick={close}>×</button></div><form onSubmit={submit}><Fields modal={modal} context={context} data={data} act={act} panelConfig={panelConfig} macrosControl={modal==="nutrition"?<MacrosTrackingControls person={(data.participants||[]).find(x=>String(x.id)===String(context.id))||context} act={act}/>:null}/>{modal==="nutrition"&&(data.viewer.role==="admin"&&(String(context.nutrition_status||"")==="approved"||Boolean(context.nutrition_has_approved))?<><label className="upload">Guía nutricional PDF (admin)<input type="file" accept="application/pdf,.pdf" onChange={e=>pickFile(e.target.files?.[0])}/><span>{uploadStatus(`✓ PDF cargado${uploadedName?`: ${uploadedName}`:""} · visible para el alumno en Contenido/Herramientas y Alimentación (clic para reemplazar)`,"＋ Adjuntar guía (máx. 10 MB)")}<small>Al pulsar “Guardar plan” la guía seleccionada queda asociada al plan del alumno.</small></span></label>{uploadError&&<p className="upload-error" role="alert">No se pudo subir la guía: {uploadError}</p>}</>:<p className="modal-context">{String(context.nutrition_status||"")==="approved"||Boolean(context.nutrition_has_approved)?(context.pdf_key?"✓ Guía PDF cargada por el administrador.":"La guía PDF la adjunta el administrador."):"Primero aprueba el plan; después el administrador adjunta la guía PDF."}</p>)}{modal==="content"&&<><label className="upload">Archivo (PDF, imagen u otro)<input type="file" accept="application/pdf,image/*,.pdf,.png,.jpg,.jpeg" onChange={e=>pickFile(e.target.files?.[0])}/><span>{uploadStatus(`✓ Archivo cargado${uploadedName?`: ${uploadedName}`:""}`,"＋ Subir archivo (opcional si ya hay video o link)")}</span></label>{uploadError&&<p className="upload-error" role="alert">No se pudo subir el archivo: {uploadError}</p>}</>}<div className="editor-actions"><button type="button" className="secondary" onClick={close}>Cancelar</button><button className="primary" disabled={saving}>{saving?(uploading?"Subiendo guía…":"Guardando…"):modal==="nutrition"?"Guardar plan":"Guardar cambios"}</button></div></form></section></div>}

function ProfessionalStudentFile({context,data,close,act,panelConfig}:{context:Row;data:AppData;close:()=>void;act:(x:Row)=>Promise<unknown>;panelConfig:PanelConfig|null}){
  const [programChoice,setProgramChoice]=useState(String(context.program_id||""));
  const [emergencyChoice,setEmergencyChoice]=useState(String(context.emergency_program_id||""));
  const [guideTab,setGuideTab]=useState<"primary"|"emergency">("primary");
  const [effectiveFrom,setEffectiveFrom]=useState(chileTodayIso);
  const nutrition=data.professionalSpecialty==="nutrition"; const name=`${context.first_name||""} ${context.last_name||""}`.trim()||String(context.email||"Alumno");
  const approved=nutrition?String(context.nutrition_status)==="approved":String(context.training_approval_status)==="approved";
  const guide=(data.programGuides||[]).find(x=>String(x.program_id)===String(context.program_id));
  const emergencyGuide=(data.programGuides||[]).find(x=>String(x.program_id)===String(context.emergency_program_id));
  const workouts=(data.workouts||[]).filter(x=>String(x.program_id)===String(context.program_id));
  const weight=Number(context.weight||0), calories=Number(context.calories||0); let referenceWeight=weight;try{referenceWeight=Number((JSON.parse(String(context.nutrition_assessment||"{}")) as {referenceWeight?:number}).referenceWeight||weight)}catch{/* Fall back to current weight. */}
  const macros=[{name:"Proteínas",grams:Number(context.protein||0),factor:4},{name:"Carbohidratos",grams:Number(context.carbs||0),factor:4},{name:"Grasas / lípidos",grams:Number(context.fats||0),factor:9}];
  const canApprove=nutrition?Boolean(context.nutrition_id):Boolean(context.program_id);
  const activeGuide=guideTab==="emergency"?emergencyGuide:guide;
  const emergencyAssignments=nutrition?null:<div className="coach-program-assignment emergency"><label>Rutina de emergencia (casa)<select value={emergencyChoice} onChange={e=>setEmergencyChoice(e.target.value)}><option value="">Sin rutina de emergencia…</option>{(data.programs||[]).filter(program=>String(program.id)!==String(context.program_id)).map(program=><option key={String(program.id)} value={String(program.id)}>{String(program.name)}</option>)}</select></label><button className="primary" disabled={!emergencyChoice||emergencyChoice===String(context.emergency_program_id||"")} onClick={async()=>{await act({action:"program.assign",userId:context.id,programId:emergencyChoice,kind:"emergency"});setGuideTab("emergency")}}>{context.emergency_program_id?"Cambiar emergencia":"Asignar emergencia"}</button></div>;
  return <div className="modal-backdrop" onMouseDown={e=>e.target===e.currentTarget&&close()}><section className="editor-modal professional-student-modal"><div className="modal-head"><div><span className="eyebrow">{nutrition?"EXPEDIENTE NUTRICIONAL":"EXPEDIENTE DE ENTRENAMIENTO"}</span><h2>{name}</h2><p>{String(context.email||"")}</p></div><button onClick={close}>×</button></div>
    <div className="professional-file-summary"><span><small>Peso inicial</small><b>{weight?`${weight} kg`:"—"}</b></span><span><small>Estatura</small><b>{formatHeightCm(context.height)}</b></span><span><small>Último peso</small><b>{context.latest_weight?`${context.latest_weight} kg`:"—"}</b></span><span><small>{nutrition?"Plan nutricional":"Rutina asignada"}</small><b>{nutrition?(context.nutrition_id?"Calculado":"Sin calcular"):String(context.program_name||"Sin asignar")}</b></span><span><small>Aprobación profesional</small><b className={approved?"approved-text":"pending-text"}>{approved?"✓ Aprobado":"Pendiente"}</b></span></div><ProgressMilestones person={context} currentDay={Number(context.adherence_elapsed_days||0)} panelConfig={panelConfig}/>
    {!nutrition&&<><section className="professional-file-section professional-intake"><div className="professional-file-heading"><div><span className="eyebrow">PASO 1 · ANTECEDENTES DEL FORMULARIO</span><h3>Revisa las respuestas del alumno</h3><p>Visibilidad: Coach + Ambos.</p></div></div><IntakeResponses participant={context} questions={data.intakeQuestions||[]} responses={data.intakeResponses||[]}/></section><TrainingDailyReview records={data.habitDaily||[]} person={context} panelConfig={panelConfig}/></>}
    {nutrition&&<><NutritionAssessmentPanel person={context}/><NutritionDailyReview records={data.nutritionDaily||[]} person={context} panelConfig={panelConfig}/></>}
    {nutrition?<section className="professional-file-section"><div className="professional-file-heading"><div><span className="eyebrow">DISTRIBUCIÓN DIARIA</span><h3>Macronutrientes calculados</h3></div><strong>{calories?`${calories} kcal`:"Sin calcular"}</strong></div>{context.nutrition_id?<div className="professional-macro-table"><div className="professional-macro-row macro-head"><span>Macronutriente</span><span>% energía</span><span>Energía</span><span>Gramos</span><span>g/kg ref.</span></div>{macros.map(m=>{const energy=m.grams*m.factor;return <div className="professional-macro-row" key={m.name}><b>{m.name}</b><span>{calories?`${Math.round(energy/calories*100)}%`:"—"}</span><span>{m.grams?`${energy} kcal`:"—"}</span><span>{m.grams?`${m.grams} g`:"—"}</span><span>{referenceWeight&&m.grams?(m.grams/referenceWeight).toFixed(2):"—"}</span></div>})}</div>:<div className="professional-file-empty"><b>Plan aún no calculado</b><p>Completa los macros desde la vista de Nutrición antes de aprobar.</p></div>}</section>
    :<section className="professional-file-section routine-file-section"><div className="professional-file-heading"><div><span className="eyebrow">PASO 2 · ASIGNACIÓN DE RUTINA</span><h3>{String(context.program_name||"Rutina sin asignar")}</h3></div></div><div className="coach-program-assignment"><label>Rutina principal<select value={programChoice} onChange={e=>setProgramChoice(e.target.value)}><option value="">Selecciona una rutina…</option>{(data.programs||[]).map(program=><option key={String(program.id)} value={String(program.id)}>{String(program.name)}</option>)}</select></label><button className="primary" disabled={!programChoice||programChoice===String(context.program_id||"")} onClick={async()=>{await act({action:"program.assign",userId:context.id,programId:programChoice,kind:"primary"});setGuideTab("primary");close()}}>{context.program_id?"Cambiar principal":"Asignar principal"}</button></div>{emergencyAssignments}{(guide||emergencyGuide)&&<nav className="routine-kind-tabs" aria-label="Rutinas del alumno">{guide&&<button className={guideTab==="primary"?"active":""} onClick={()=>setGuideTab("primary")}>Principal · {String(context.program_name||"")}</button>}{emergencyGuide&&<button className={guideTab==="emergency"?"active":""} onClick={()=>setGuideTab("emergency")}>Emergencia (casa) · {String(context.emergency_program_name||"")}</button>}</nav>}{activeGuide?<RoutineGuide guideRow={activeGuide} exercises={data.exercises||[]}/>:workouts.length?<div className="fallback-workouts">{workouts.map(x=><article key={String(x.id)}><b>{String(x.title||x.name||"Sesión")}</b><p>{String(x.description||"Rutina asignada al alumno.")}</p></article>)}</div>:<div className="professional-file-empty"><b>Sin rutina asignada</b><p>Después de revisar sus respuestas, selecciona la rutina correspondiente.</p></div>}</section>}
    {nutrition&&<section className="professional-file-section professional-intake"><div className="professional-file-heading"><div><span className="eyebrow">ANTECEDENTES DEL FORMULARIO</span><h3>Preguntas y respuestas del alumno</h3><p>Visibilidad: Nutrición + Ambos.</p></div></div><IntakeResponses participant={context} questions={data.intakeQuestions||[]} responses={data.intakeResponses||[]}/></section>}
    {nutrition&&<MacrosTrackingControls person={context} act={act}/>}
    <StaffNotesPanel notes={data.notes||[]} userId={String(context.id)} act={act} canDelete={data.viewer.role==="admin"}/>
    <div className="professional-approval-bar"><div><span className={`approval-dot ${approved?"approved":""}`}>{approved?"✓":"!"}</span><span><b>{approved?"Asignación aprobada":"Revisión profesional pendiente"}</b><small>{approved?"El alumno puede guiarse por esta versión.":"Revisa la ficha completa antes de aprobar."}</small></span></div>{!approved&&nutrition?<label className="effective-from-field">Vigente desde<input type="date" value={effectiveFrom} onChange={e=>setEffectiveFrom(e.target.value||chileTodayIso())}/><small>Por defecto hoy. Define desde cuándo aplica esta meta.</small></label>:null}{!approved&&<button className="primary" disabled={!canApprove} onClick={async()=>{await act({action:nutrition?"nutrition.review":"training.review",userId:context.id,...(nutrition?{effectiveFrom}:{})});close()}}>{canApprove?nutrition?"Aprobar plan nutricional":"Aprobar rutina asignada":nutrition?"Primero calcula el plan":"Primero asigna una rutina"}</button>}</div>
  </section></div>
}

function Fields({modal,context,data,act,macrosControl,panelConfig}:{modal:Exclude<Modal,null>;context:Row;data:AppData;act:(x:Row)=>Promise<unknown>;macrosControl?:React.ReactNode;panelConfig?:PanelConfig|null}){if(modal==="participant"||modal==="participant-edit")return <><div className="access-explainer"><b>Acceso del participante</b><p>Al guardar, se genera una contraseña temporal y se envía por correo a esta misma dirección; también podrás copiarla aquí para reenviarla. El día 1 del desafío parte cuando coach y nutri aprueban el plan; el administrador puede ajustarlo desde la ficha.</p></div><div className="form-grid two"><Field n="firstName" l="Nombre" d={context.first_name} required/><Field n="lastName" l="Apellido" d={context.last_name}/><Field n="email" l="Correo de acceso a 90 días" d={context.email} type="email" disabled={modal==="participant-edit"} required/><Field n="city" l="Ciudad" d={context.city}/><Field n="objective" l="Objetivo principal" d={context.objective}/><Field n="trainingDays" l="Días disponibles" d={context.training_days??panelConfig?.default_sessions_per_week??3} type="number"/></div><div className="form-grid two"><Select n="location" l="Lugar" d={context.preferred_location} opts={["Casa","Gimnasio","Ambos"]}/><Select n="activityLevel" l="Actividad" d={context.activity_level} opts={["Sedentario","Mixto","Activo"]}/>{modal==="participant"&&<Select n="programId" l="Programa inicial" opts={["",...(data.programs||[]).map(x=>String(x.id))]} labels={["Asignar después",...(data.programs||[]).map(x=>String(x.name))]}/>} {modal==="participant-edit"&&<Select n="status" l="Estado" d={context.status} opts={["invited","onboarding","review","configuration","active","finished"]}/>}</div>{modal==="participant-edit"&&<div className="access-explainer"><b>Adherencia calculada automáticamente</b><p>Los porcentajes se alimentan de los registros diarios del alumno y no se editan manualmente.</p></div>}{modal==="participant-edit"&&data.viewer.role==="admin"&&<div className="access-explainer"><b>Peso, estatura, fecha de nacimiento y género</b><p>Se corrigen con «Editar datos» en Participantes o en la Ficha del alumno (también los pesos de los días 30, 60 y 90).</p></div>}<Area n="restrictions" l="Restricciones alimentarias" d={context.dietary_restrictions}/><Area n="motivation" l="¿Por qué quiere hacer Proyecto 90?" d={context.motivation}/> </>;
if(modal==="professional"||modal==="professional-edit")return <><div className="access-explainer"><b>Acceso profesional</b><p>Autoriza el correo que utilizará el profesional. Su especialidad define las respuestas, alumnos y aprobaciones disponibles en su panel.</p></div><div className="form-grid two"><Field n="firstName" l="Nombre" d={context.first_name} required/><Field n="lastName" l="Apellido" d={context.last_name}/><Field n="email" l="Correo autorizado" d={context.email} type="email" required/><Select n="specialty" l="Especialidad" d={context.specialty||"coach"} opts={["coach","nutrition"]} labels={["Coach / preparador físico","Nutricionista"]}/>{modal==="professional-edit"&&<Select n="status" l="Estado" d={context.status||"active"} opts={["active","inactive"]} labels={["Activo","Inactivo"]}/>}</div></>;
if(modal==="admin"||modal==="admin-edit")return <><div className="access-explainer"><b>Acceso administrador</b><p>Este perfil podrá ver y gestionar administradores, profesionales, alumnos, programas, nutrición y adherencia.</p></div><div className="form-grid two"><Field n="firstName" l="Nombre" d={context.first_name} required/><Field n="lastName" l="Apellido" d={context.last_name}/><Field n="email" l="Correo autorizado" d={context.email} type="email" required/>{modal==="admin-edit"&&<Select n="status" l="Estado" d={context.status||"active"} opts={["active","inactive"]} labels={["Activo","Inactivo"]}/>}</div></>;
if(modal==="program")return <><Field n="name" l="Nombre del programa" placeholder="Ej. Casa Avanzado" required/><div className="form-grid two"><Select n="level" l="Nivel" opts={["Inicial","Intermedio","Avanzado"]}/><Select n="location" l="Lugar" opts={["Casa","Gimnasio","Ambos"]}/></div></>;
if(modal==="workout"||modal==="workout-edit")return <><p className="modal-context">{modal==="workout"?<>Programa: <b>{String(context.name)}</b></>:"Edita el nombre y la ubicación temporal de esta rutina."}</p><Field n="name" l="Nombre de la rutina" d={context.name} placeholder="Ej. Rutina A · Fuerza base" required/><div className="form-grid two"><Field n="month" l="Mes" type="number" d={context.month||1}/><Field n="week" l="Semana" type="number" d={context.week||1}/></div></>;
if(modal==="exercise"||modal==="exercise-edit")return <><div className="form-grid two"><Field n="name" l="Nombre del ejercicio" d={context.name} required/><Field n="youtubeUrl" l="Video YouTube no listado" d={context.youtube_url} placeholder="https://youtube.com/watch?v=…" type="url"/><Field n="category" l="Categoría" d={context.category} placeholder="Piernas, empuje…"/><Select n="level" l="Nivel" d={context.level} opts={["Inicial","Intermedio","Avanzado"]}/></div><Area n="description" l="Descripción" d={context.description}/><Area n="technique" l="Técnica" d={context.technique}/><Area n="commonErrors" l="Errores frecuentes" d={context.common_errors}/><div className="form-grid two"><Field n="regression" l="Regresión" d={context.regression}/><Field n="progression" l="Progresión" d={context.progression}/></div></>;
if(modal==="attach"||modal==="attach-edit")return <><p className="modal-context">{modal==="attach"?<>Rutina: <b>{String(context.name)}</b></>:<>Ejercicio: <b>{String(context.exercise_name)}</b></>}</p>{modal==="attach"&&<Select n="exerciseId" l="Ejercicio de la biblioteca" opts={(data.exercises||[]).map(x=>String(x.id))} labels={(data.exercises||[]).map(x=>String(x.name))}/>}<div className="form-grid three"><Field n="sets" l="Series" type="number" d={context.sets||3}/><Field n="reps" l="Repeticiones" d={context.reps||10}/><Field n="restSeconds" l="Descanso (seg)" type="number" d={context.rest_seconds||60}/></div><Area n="notes" l="Notas para el alumno" d={context.notes}/></>;
if(modal==="nutrition")return <><p className="modal-context"><b>{`${context.first_name||""} ${context.last_name||""}`}</b> · {String(context.objective||"Sin objetivo")} · Peso: <b>{context.weight?`${context.weight} kg`:"No informado"}</b> · Estatura: <b>{formatHeightCm(context.height,"No informada")}</b></p><ProgressMilestones person={context} currentDay={Number(context.adherence_elapsed_days||0)} panelConfig={panelConfig}/><NutritionPlanFields person={context} act={act} canRecalculate={data.viewer.role==="admin"||data.viewer.role==="professional"}><NutritionDailyReview records={data.nutritionDaily||[]} person={context} panelConfig={panelConfig}/></NutritionPlanFields>{macrosControl}<Select n="status" l="Estado del plan" d={context.nutrition_status||"pending_review"} opts={["pending_review","approved","rejected"]} labels={["Por revisar","Aprobar y publicar","Rechazar / devolver"]}/><Area n="notes" l="Comentario profesional" d={context.nutrition_notes}/><div className="form-grid two"><Field n="effectiveFrom" l="Vigente desde" type="date" d={context.effective_from||chileTodayIso()}/><Field n="reviewDate" l="Fecha de revisión" type="date" d={context.review_date}/></div><p className="modal-context">«Vigente desde» es la fecha en que empieza a aplicar esta meta (por defecto hoy).</p></>;
if(modal==="content")return <><div className="form-grid two"><Field n="title" l="Título" required/><Select n="category" l="Categoría" opts={["Hábitos","Nutrición","Entrenamiento","Sesiones"]}/></div><Area n="description" l="Descripción"/><div className="form-grid two"><Field n="videoUrl" l="Video YouTube (opcional)" type="url" d={context.video_url}/><Select n="fileKind" l="Tipo de archivo" d={context.file_kind||"video"} opts={["pdf","image","link","video"]} labels={["PDF","Imagen","Link","Video"]}/></div><p className="modal-context">Puedes publicar un video, un link o subir un PDF/imagen. Si subes archivo, el tipo debe coincidir.</p><div className="form-grid two"><Field n="position" l="Orden" type="number" d="1"/><Field n="publishAt" l="Publicar desde" type="datetime-local"/></div></>;
if(modal==="meeting-review")return <><p className="modal-context"><b>{`${context.first_name||""} ${context.last_name||""}`}</b> · {String(context.email||"")}</p><p className="modal-context">Horario solicitado: {new Date(String(context.requested_at)).toLocaleString("es-CL")}</p><Select n="status" l="Decisión" d={context.status==="pending"?"confirmed":context.status} opts={["confirmed","rescheduled","rejected"]} labels={["Aprobar","Reprogramar","Rechazar"]}/><Field n="startsAt" l="Fecha y hora definitiva" type="datetime-local" d={context.starts_at||context.requested_at} required/><Field n="meetingLink" l="Enlace Google Meet o Zoom (obligatorio al aprobar)" type="url" d={context.meeting_link}/><Area n="adminNote" l="Nota para el alumno" d={context.admin_note}/></>;
const pros=data.professionals||[];const proIds=pros.map(row=>String(row.id));const proLabels=pros.map(row=>`${row.first_name||""} ${row.last_name||""}`.trim()||String(row.email||"Profesional"));const selectedProfessional=String(context.professional_user_id||proIds.find((_,i)=>proLabels[i]===String(context.professional||""))||proIds[0]||"");return <><Field n="title" l="Nombre de la sesión" d={context.title} required/><div className="form-grid two">{proIds.length?<Select n="professionalId" l="Profesional" d={selectedProfessional} opts={proIds} labels={proLabels}/>:<Field n="professional" l="Profesional" d={context.professional}/>}<Field n="startsAt" l="Fecha y hora" type="datetime-local" d={context.starts_at} required/></div><Field n="link" l="Enlace en vivo (opcional)" type="url" d={context.link} placeholder="Puedes agregarlo después"/><Field n="recordingUrl" l="Grabación YouTube (opcional)" type="url" d={context.recording_url} placeholder="Puedes agregarlo después"/></>}

function Title({eyebrow,title,copy,action}:{eyebrow:string;title:string;copy:string;action?:React.ReactNode}){return <div className="admin-title"><div><span className="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{copy}</p></div>{action}</div>}
function Metric({label,value,note,green=false}:{label:string;value:string;note:string;green?:boolean}){return <article className={`metric ${green?"green":""}`}><div className="metric-head"><span className="metric-icon">{green?"✓":"◎"}</span><span>{label}</span></div><strong>{value}</strong><small>{note}</small></article>}
function Empty({title,copy,action}:{title:string;copy:string;action?:React.ReactNode}){return <article className="empty-state"><span className="icon-tile green">＋</span><h2>{title}</h2><p>{copy}</p>{action}</article>}
function Status({text}:{text:string}){const labels:Record<string,string>={invited:"Invitado",onboarding:"Onboarding",review:"En revisión",configuration:"Configuración",active:"Activo",finished:"Finalizado"};const shown=labels[text]||text;return <span className={`status ${text.toLowerCase().replace(/\s/g,"-")}`}>{shown}</span>}
function Field({n,l,d="",type="text",placeholder="",required=false,disabled=false}:{n:string;l:string;d?:unknown;type?:string;placeholder?:string;required?:boolean;disabled?:boolean}){const shown=type==="datetime-local"?toLocalInput(d):String(d||"");return <label>{l}<input name={n} defaultValue={shown} type={type} placeholder={placeholder} required={required} disabled={disabled}/></label>}
function Area({n,l,d=""}:{n:string;l:string;d?:unknown}){return <label>{l}<textarea name={n} defaultValue={String(d||"")}/></label>}
function Select({n,l,d="",opts,labels}:{n:string;l:string;d?:unknown;opts:string[];labels?:string[]}){return <label>{l}<select name={n} defaultValue={String(d||opts[0]||"")}>{opts.map((x,i)=><option value={x} key={x}>{labels?.[i]||x}</option>)}</select></label>}
function actionFor(m:Exclude<Modal,null>){return ({participant:"participant.create",professional:"professional.create","professional-edit":"professional.update",admin:"admin.create","admin-edit":"admin.update","participant-edit":"participant.update",program:"program.create",workout:"workout.create","workout-edit":"workout.update",exercise:"exercise.create","exercise-edit":"exercise.update",attach:"workout.exercise.add","attach-edit":"workout.exercise.update",nutrition:"nutrition.save",content:"content.create",session:"session.create","meeting-review":"meeting.review"} as Record<string,string>)[m]}
function modalTitle(m:Exclude<Modal,null>,c:Row){return ({participant:"Crear participante",professional:"Crear profesional","professional-edit":"Editar profesional",admin:"Crear administrador","admin-edit":"Editar administrador","participant-edit":"Editar participante",program:"Crear programa",workout:"Agregar rutina","workout-edit":"Editar rutina",exercise:"Agregar ejercicio y video","exercise-edit":"Editar ejercicio y video",attach:`Agregar ejercicio a ${String(c.name||"rutina")}`,"attach-edit":`Editar ${String(c.exercise_name||"ejercicio")}`,nutrition:"Editar nutrición",content:"Publicar contenido",session:c.id?"Editar sesión":"Crear sesión","meeting-review":"Gestionar reunión individual"} as Record<string,string>)[m]}
function initials(n:string){return n.split(" ").filter(Boolean).slice(0,2).map(x=>x[0]?.toUpperCase()).join("")||"90"} function first(n:string){return n.split(" ")[0]||"Moya"} function roleLabel(r:string){return r==="admin"?"Administrador":r==="professional"?"Profesional":r==="reviewer"?"Revisor":"Participante"}
function dayOf90(row:Row,challengeDays=PANEL_CONFIG_DEFAULTS.challenge_length_days){const raw=row.challenge_start||row.assigned_at||row.created_at;if(!raw)return 0;const start=new Date(`${String(raw).slice(0,10)}T12:00:00Z`).getTime();if(Number.isNaN(start))return 0;const days=Math.floor((appNow-start)/86400000);const len=Number(challengeDays)||PANEL_CONFIG_DEFAULTS.challenge_length_days;return days<0?0:Math.max(1,Math.min(len,days+1))}

function MacrosTrackingControls({person,act}:{person:Row;act:(x:Row)=>Promise<unknown>}){
  const deferred=String(person.macros_tracking||"")==="deferred";
  const [saving,setSaving]=useState(false);
  return <div className="macros-tracking-bar"><div><b>{deferred?"Macros pausados":"Macros activos"}</b><p>{deferred?"El alumno no gestiona el tracker hasta que liberes el seguimiento.":"El alumno ve objetivos y puede registrar macros diarios."}</p></div><button type="button" className="secondary" disabled={saving} onClick={async()=>{setSaving(true);try{await act({action:"macros.tracking.set",userId:person.id,mode:deferred?"active":"deferred"})}finally{setSaving(false)}}}>{saving?"Guardando…":deferred?"Liberar macros":"Pausar macros (no gestionar)"}</button></div>;
}

function StartChallengeEditor({context,act}:{context:Row;act:(x:Row)=>Promise<unknown>}){
  const initial=String(context.challenge_start||"").slice(0,10);
  const [value,setValue]=useState(initial); const [saved,setSaved]=useState(initial); const [saving,setSaving]=useState(false);
  const dirty=Boolean(value)&&value!==saved;
  return <div className="start-challenge-editor"><div><b>Fecha de inicio del desafío (día 1)</b><p>El día 1 oficial parte cuando el alumno tiene rutinas y macros asignados. Puedes moverlo a mano (p. ej. al 01-10-2026).</p></div><div className="start-challenge-controls"><input type="date" value={value} onChange={e=>setValue(e.target.value)} aria-label="Fecha de inicio del desafío"/><button className="secondary" disabled={saving||!dirty} onClick={async()=>{setSaving(true);try{await act({action:"participant.update",id:context.id,challengeStart:value});setSaved(value)}finally{setSaving(false)}}}>{saving?"Guardando…":dirty?"Guardar fecha de inicio":"Guardado ✓"}</button></div></div>;
}

function ParticipantTraining({guide,emergencyGuide,exercises}:{guide?:Row;emergencyGuide?:Row;exercises:Row[]}){
  const hasBoth=Boolean(guide&&emergencyGuide);
  const [tab,setTab]=useState<"primary"|"emergency">("primary");
  const active=tab==="emergency"&&emergencyGuide?emergencyGuide:guide;
  if(!active)return null;
  return <div className="participant-training">{hasBoth&&<nav className="routine-kind-tabs" aria-label="Rutinas disponibles">{guide&&<button className={tab!=="emergency"?"active":""} onClick={()=>setTab("primary")}>Mi rutina principal</button>}{emergencyGuide&&<button className={tab==="emergency"?"active":""} onClick={()=>setTab("emergency")}>Emergencia · para entrenar en casa</button>}</nav>}<RoutineGuide guideRow={active} exercises={exercises}/></div>;
}
function countRiskyParticipants(records:Row[],nutrition:Row[]=[],people:Row[]=[],panelConfig?:PanelConfig|null){const tz=panelConfig?.timezone||PANEL_CONFIG_DEFAULTS.timezone;const today=new Intl.DateTimeFormat("en-CA",{timeZone:tz,year:"numeric",month:"2-digit",day:"2-digit"}).format(new Date()),now=new Date(`${today}T12:00:00Z`),weekStart=panelConfig?.week_start_weekday??PANEL_CONFIG_DEFAULTS.week_start_weekday,asMon0=((now.getUTCDay()+6)%7),delta=(asMon0-((weekStart%7)+7)%7+7)%7,monday=new Date(now.getTime()-delta*86400000).toISOString().slice(0,10);const all=buildEffectiveRecords(people,records,nutrition,panelConfig),lookup=new Map(all.map(row=>[`${row.user_id}:${row.habit}:${row.habit_date}`,row.status])),risky=new Set<string>();for(const person of people){const id=String(person.id),start=String(person.challenge_start||person.assigned_at||person.created_at||monday).slice(0,10);for(const habit of ["training","macros"]){let streak=0;for(let cursor=new Date(`${monday}T12:00:00Z`);cursor.toISOString().slice(0,10)<today;cursor=new Date(cursor.getTime()+86400000)){const date=cursor.toISOString().slice(0,10);if(date<start)continue;streak=lookup.get(`${id}:${habit}:${date}`)==="missed"?streak+1:0;const need=panelConfig?.alert_min_affected_days??PANEL_CONFIG_DEFAULTS.alert_min_affected_days;if(streak>=Math.max(1,need)){risky.add(id);break}}}}return risky.size}
